INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (429, 1, 'primitive', '필터의 **primitive** 는 어떻게 구성될까요?', '한정자와 id 예요.', NULL, NULL, '[]', 'choice', '["연산자 뒤에 숫자가 붙는다", "프로토콜 이름 하나만 쓴다", "보통 id 앞에 한정자가 붙는다", "괄호 안에 정규식을 쓴다"]', 2, 'pcap-filter 문서는 primitive 가 보통 id 앞에 하나 이상의 한정자가 붙는 구조라고 설명합니다.', NULL, NULL, NULL, '[{"title": "pcap-filter(7) man page", "url": "https://man7.org/linux/man-pages/man7/pcap-filter.7.html"}]'),
  (429, 2, '한정자 종류', '필터 한정자의 **세 종류** 는 무엇일까요?', '유형·방향·프로토콜이에요.', NULL, NULL, '[]', 'choice', '["host, port, net", "type, dir, proto", "src, dst, any", "tcp, udp, icmp"]', 1, '문서는 한정자를 type(host·net·port·portrange), dir(src·dst), proto(ether·ip·tcp·udp 등) 세 종류로 설명합니다.', NULL, NULL, NULL, '[{"title": "pcap-filter(7) man page", "url": "https://man7.org/linux/man-pages/man7/pcap-filter.7.html"}]'),
  (429, 3, '결합', '여러 primitive 를 **결합** 하는 연산자는 무엇일까요?', '논리 연산이에요.', NULL, NULL, '[]', 'choice', '["and, or, not", "union, minus, plus", "+, -, *", "if, then, else"]', 0, '문서는 and, or, not(각각 &&, ||, !)으로 primitive 를 결합하며 괄호도 쓸 수 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "pcap-filter(7) man page", "url": "https://man7.org/linux/man-pages/man7/pcap-filter.7.html"}]'),
  (429, 4, 'host 의 의미', '`host foo` 는 어떤 패킷에 일치할까요?', '방향을 안 줬어요.', NULL, NULL, '[]', 'choice', '["목적지 주소가 foo 인 패킷만", "출발지 주소가 foo 인 패킷만", "foo 가 응답한 패킷만", "출발지 또는 목적지 주소가 foo 인 패킷"]', 3, '문서는 host foo 가 패킷의 출발지 또는 목적지 주소가 해당 호스트이면 참이 된다고 설명합니다.', NULL, NULL, NULL, '[{"title": "pcap-filter(7) man page", "url": "https://man7.org/linux/man-pages/man7/pcap-filter.7.html"}]'),
  (429, 5, 'dir 생략', '한정자에 **dir 을 생략** 하면 어떻게 볼까요?', '둘 다예요.', NULL, NULL, '[]', 'choice', '["src 한쪽만 본다", "dst 한쪽만 본다", "src or dst", "오류로 거부된다"]', 2, '문서는 한정자에 dir 이 없으면 src or dst 로 간주한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "pcap-filter(7) man page", "url": "https://man7.org/linux/man-pages/man7/pcap-filter.7.html"}]'),
  (429, 6, 'portrange', '`portrange 6000-6008` 은 무엇일까요?', '범위예요.', NULL, NULL, '[]', 'choice', '["포트 6000 과 6008 에만 일치", "포트 6000 에서 6008 사이에 일치", "포트 6008 개를 한꺼번에 막음", "포트 번호의 합이 6008 인 패킷"]', 1, '문서는 portrange 6000-6008 과 udp portrange 7000-7009 같은 예시로 포트 범위 일치를 설명합니다.', NULL, NULL, NULL, '[{"title": "pcap-filter(7) man page", "url": "https://man7.org/linux/man-pages/man7/pcap-filter.7.html"}]'),
  (429, 7, 'icmp', '`icmp` 는 문서에서 무엇의 축약형일까요?', 'ip proto 로 풀어요.', NULL, NULL, '[]', 'choice', '["ip proto 1", "ip proto 6", "ether proto 1", "tcp proto 1"]', 0, '문서는 icmp 를 proto 한정자 목록이 아니라 ip proto 1 의 축약형으로 설명합니다.', NULL, NULL, NULL, '[{"title": "pcap-filter(7) man page", "url": "https://man7.org/linux/man-pages/man7/pcap-filter.7.html"}]'),
  (429, 8, 'less 와 길이', '`less N` 은 무엇과 같을까요?', '길이 비교예요.', NULL, NULL, '[]', 'choice', '["len >= N", "len == N", "len < N - 1", "len <= N"]', 3, '문서는 less N 이 len <= N, greater N 이 len >= N 과 같다고 설명합니다.', NULL, NULL, NULL, '[{"title": "pcap-filter(7) man page", "url": "https://man7.org/linux/man-pages/man7/pcap-filter.7.html"}]'),
  (429, 9, 'vlan', '`vlan` primitive 는 무엇을 판별할까요?', '802.1Q 예요.', NULL, NULL, '[]', 'choice', '["VXLAN 터널 패킷인지", "가상 머신의 패킷인지", "802.1Q VLAN 패킷인지", "브리지를 지난 패킷인지"]', 2, '문서는 vlan 이 IEEE 802.1Q VLAN 패킷인지 판별하며 선택적으로 vlan_id 를 지정할 수 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "pcap-filter(7) man page", "url": "https://man7.org/linux/man-pages/man7/pcap-filter.7.html"}]'),
  (429, 10, '포트 지정', 'TCP **80 포트** 패킷을 고르는 type 한정자입니다. 빈칸을 채우세요.', '"포트" 예요.', NULL, NULL, '[]', 'fill', '["port", "host", "net", "proto"]', NULL, 'tcp port 80 처럼 proto 한정자 뒤에 port type 한정자를 씁니다.', '[0]', 'tcpdump -i eth0 tcp {0} 80', NULL, '[{"title": "pcap-filter(7) man page", "url": "https://man7.org/linux/man-pages/man7/pcap-filter.7.html"}]'),
  (429, 11, '출발지만', '**출발지** 주소만 맞추는 dir 한정자입니다. 빈칸을 채우세요.', '"source" 의 줄임이에요.', NULL, NULL, '[]', 'fill', '["src", "dst", "ether", "ip"]', NULL, 'src 는 출발지, dst 는 목적지 방향 한정자입니다. dir 을 생략하면 src or dst 입니다.', '[0]', 'tcpdump -i eth0 {0} host 10.0.0.5', NULL, '[{"title": "pcap-filter(7) man page", "url": "https://man7.org/linux/man-pages/man7/pcap-filter.7.html"}]'),
  (429, 12, '필터 만들기', 'tcpdump 필터를 만드는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '유형 → 방향 → 프로토콜 → 결합이에요.', NULL, NULL, '[]', 'order', '["`host`·`net`·`port` 같은 type 으로 대상을 정한다", "필요하면 `src`·`dst` 로 방향을 정한다", "`tcp`·`udp` 같은 proto 로 프로토콜을 좁힌다", "`and`·`or`·`not` 으로 여러 조건을 결합한다"]', NULL, '문서의 한정자와 결합 설명을 이은 일반 절차입니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "pcap-filter(7) man page", "url": "https://man7.org/linux/man-pages/man7/pcap-filter.7.html"}]');
